(function () {
'use strict';
const API = '/api/associations';
const state = { page: 1, pageSize: 20, search: '', organization_id: '', status: '', area_code: '', from_age: '', to_age: '', catalogs: null, suggestions: [] };
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value == null ? '' : value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
const num = value => new Intl.NumberFormat('vi-VN').format(Number(value || 0));
const date = value => value ? new Intl.DateTimeFormat('vi-VN').format(new Date(value)) : '';
let registered = false;
let citizenSearchSequence = 0;
let duplicateCheckSequence = 0;
register();
document.addEventListener('DOMContentLoaded', init);
document.addEventListener('tenant:screen-change', event => { if (event.detail?.screen === 'associations') load(); });
function register() {
if (registered || !window.TenantAppPlatform) return;
registered = true;
const platform = window.TenantAppPlatform;
try {
platform.modules?.register?.({ moduleKey: 'associations', screenId: 'associations', path: '/associations', label: 'Doan the', mobileLabel: 'Doan the', icon: 'fa-people-group', permissionScope: 'associations', loaderName: 'loadAssociations' });
platform.routes?.register?.({ path: '/associations', moduleKey: 'associations', screenId: 'associations', action: 'list' });
} catch (_) {}
const actions = platform.actions;
[['associations.search', () => { collect(); state.page = 1; load(); }], ['associations.reset', reset], ['associations.openCreate', () => openForm()], ['associations.edit', control => openForm(Number(control.dataset.id))], ['associations.delete', control => leave(Number(control.dataset.id))], ['associations.export', exportCsv], ['associations.print', printReport], ['associations.page', control => { state.page = Number(control.dataset.page); load(); }]].forEach(([name, handler]) => actions?.register?.(name, handler));
actions?.bind?.(document);
}
function init() {
register();
const addButton = document.querySelector('[data-platform-action="associations.openCreate"]');
if (addButton && !addButton.dataset.associationsBound) { addButton.dataset.associationsBound = '1'; addButton.addEventListener('click', () => openForm()); }
$('#associationForm')?.addEventListener('submit', save);
$('#associationCitizenSearch')?.addEventListener('input', debounce(searchCitizens, 250));
$('#associationOrganizationSelect')?.addEventListener('change', checkSelectedDuplicate);
$('#associationPageSize')?.addEventListener('change', event => { state.pageSize = Number(event.target.value || 20); state.page = 1; load(); });
[['associationSearch', 'search'], ['associationOrganizationFilter', 'organization_id'], ['associationStatusFilter', 'status'], ['associationAreaFilter', 'area_code'], ['associationAgeFrom', 'from_age'], ['associationAgeTo', 'to_age']].forEach(([id, key]) => { const element = $('#' + id); element?.addEventListener('change', () => { state[key] = element.value; state.page = 1; load(); }); });
if ($('#associationsScreen')?.classList.contains('active')) load();
}
function normalizeApiData(response) {
if (Array.isArray(response)) return { items: response };
if (!response || typeof response !== 'object') return response;
if (Array.isArray(response.items)) return response;
if (Array.isArray(response.data)) return { ...response, items: response.data };
return response;
}
async function request(url, options = {}) { return normalizeApiData(await window.api?.(url, options)); }
async function ensureCatalogs() {
if (state.catalogs) return state.catalogs;
state.catalogs = await request(API + '/catalogs');
fill('#associationOrganizationFilter', state.catalogs.organizations, 'Tat ca');
fill('#associationOrganizationSelect', state.catalogs.organizations, 'Chon doan the');
fill('#associationStatusFilter', state.catalogs.statuses, 'Dang tham gia');
fill('#associationAreaFilter', state.catalogs.areas, 'Tat ca');
return state.catalogs;
}
async function load() {
if (!can('read')) return;
try { await ensureCatalogs(); collect(); const data = await request(API + '?' + params()); render(data); const dashboard = await request(API + '/dashboard?' + params()); renderDashboard(dashboard.metrics || {}); } catch (error) { toast(error.message, 'danger'); }
}
function params() { const query = new URLSearchParams({ page: state.page, pageSize: state.pageSize }); Object.entries(state).forEach(([key, value]) => { if (['catalogs', 'suggestions'].includes(key) || value === '') return; query.set(key, value); }); return query; }
function collect() { [['associationSearch', 'search'], ['associationOrganizationFilter', 'organization_id'], ['associationStatusFilter', 'status'], ['associationAreaFilter', 'area_code'], ['associationAgeFrom', 'from_age'], ['associationAgeTo', 'to_age']].forEach(([id, key]) => { state[key] = $('#' + id)?.value || ''; }); }
function suggestionHtml(item) {
const code = String(item.citizen_code || '').trim();
const household = String(item.household_code || '').trim();
const identity = String(item.identity_number || '').trim();
const address = String(item.address || '').trim();
const identifiers = [code, household].filter(Boolean);
if (identity) identifiers.push('CCCD: ' + identity);
const addressHtml = address ? '<div class="small text-muted text-wrap">Địa chỉ: ' + esc(address) + '</div>' : '';
return '<button type="button" class="list-group-item list-group-item-action text-start" data-association-citizen="' + Number(item.id) + '"><strong>' + esc(item.full_name) + '</strong><div class="small text-muted text-wrap">' + esc(identifiers.join(' · ')) + '</div>' + addressHtml + '</button>';
}
function render(data) { const rows = $('#associationRows'); const items = data.items || []; $('#associationTotalCount').textContent = 'Tong so: ' + num(data.total) + ' thanh vien'; rows.innerHTML = items.length ? items.map(row => '<tr><td><strong>' + esc(row.full_name) + '</strong><div class="text-muted small">' + esc(row.citizen_code) + '</div></td><td>' + esc(date(row.date_of_birth)) + '</td><td>' + esc(row.age) + '</td><td>' + esc(row.gender) + '</td><td>' + esc(row.household_code) + '</td><td>' + esc(row.area_code) + '</td><td>' + esc(row.organization_name) + '</td><td>' + esc(row.position_name) + '</td><td>' + esc(date(row.joined_date)) + '</td><td><span class="badge-soft">' + esc(row.status_label) + '</span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button" title="Sua" data-platform-action="associations.edit" data-id="' + row.id + '"><i class="fa-solid fa-pen"></i></button> <button class="btn btn-sm btn-outline-danger" type="button" title="Roi hoi" data-platform-action="associations.delete" data-id="' + row.id + '"><i class="fa-solid fa-user-minus"></i></button></td></tr>').join('') : '<tr><td colspan="11" class="text-center text-muted py-4">Chua co thanh vien</td></tr>'; const pager = $('#associationPager'); const pages = []; for (let page = Math.max(1, data.page - 2); page <= Math.min(data.totalPages, data.page + 2); page++) pages.push(page); pager.innerHTML = pages.map(page => '<button class="btn btn-sm ' + (page === data.page ? 'btn-primary' : 'btn-outline-secondary') + '" data-platform-action="associations.page" data-page="' + page + '">' + page + '</button>').join(''); }
function renderDashboard(metrics) { const host = $('#associationsDashboard'); if (!host) return; host.innerHTML = [['Thanh vien', metrics.total], ['Nhan khau', metrics.people], ['To chuc', metrics.organizations]].map(item => '<article class="party-kpi-card tone-green"><span class="app-v2-card-icon party-kpi-icon"><i class="fa-solid fa-people-group"></i></span><div><p>' + item[0] + '</p><strong>' + num(item[1]) + '</strong></div></article>').join(''); }
async function openForm(id = null) { await ensureCatalogs(); const form = $('#associationForm'); form.reset(); form.elements.id.value = ''; form.elements.citizen_id.value = ''; form.dataset.duplicate = ''; $('#associationCitizenSearch').disabled = false; $('#associationCitizenSelected').textContent = ''; setSaveState(); if (id) { const row = await request(API + '/' + id); form.elements.id.value = row.id; form.elements.citizen_id.value = row.citizen_id; form.elements.organization_id.value = row.organization_id; form.elements.position_name.value = row.position_name || ''; form.elements.joined_date.value = row.joined_date || ''; form.elements.card_number.value = row.card_number || ''; form.elements.status.value = row.status || 'ACTIVE'; form.elements.note.value = row.note || ''; $('#associationCitizenSearch').value = (row.citizen_code || '') + ' - ' + (row.full_name || ''); $('#associationCitizenSelected').textContent = (row.full_name || '') + ' - ' + (row.household_code || ''); $('#associationCitizenSearch').disabled = true; await checkSelectedDuplicate(); } openModal('associationModal'); }
async function searchCitizens() { const query = $('#associationCitizenSearch')?.value.trim() || ''; const requestId = ++citizenSearchSequence; if (query.length < 2) { $('#associationCitizenSuggestions')?.classList.add('d-none'); return; } const data = await request(API + '/citizen-search?q=' + encodeURIComponent(query)); const currentQuery = $('#associationCitizenSearch')?.value.trim() || ''; if (requestId !== citizenSearchSequence || query !== currentQuery) return; state.suggestions = data.items || []; const host = $('#associationCitizenSuggestions'); host.innerHTML = state.suggestions.map(suggestionHtml).join('') || '<div class="list-group-item text-muted">Khong tim thay nhan khau</div>'; host.classList.remove('d-none'); host.querySelectorAll('[data-association-citizen]').forEach(button => button.addEventListener('click', () => selectCitizen(Number(button.dataset.associationCitizen)))); }
function selectCitizen(id) { const selected = state.suggestions.find(item => Number(item.id) === id); if (!selected) return; const form = $('#associationForm'); form.elements.citizen_id.value = selected.id; $('#associationCitizenSearch').value = [selected.full_name, selected.citizen_code, selected.household_code].filter(Boolean).join(' - '); $('#associationCitizenSelected').textContent = [selected.full_name, selected.citizen_code, selected.household_code].filter(Boolean).join(' - '); $('#associationCitizenSuggestions').classList.add('d-none'); setSaveState(); checkSelectedDuplicate(); }
async function checkSelectedDuplicate() { const form = $('#associationForm'); const citizenId = Number(form?.elements.citizen_id?.value || 0); const organizationId = Number(form?.elements.organization_id?.value || 0); const sequence = ++duplicateCheckSequence; form.dataset.duplicate = ''; setSaveState(); if (!citizenId || !organizationId) return; const selected = state.suggestions.find(item => Number(item.id) === citizenId); const code = selected?.citizen_code || ($('#associationCitizenSearch')?.value.split(' - ')[0] || ''); if (!code) return; try { const data = await request(API + '?page=1&pageSize=100&organization_id=' + organizationId + '&search=' + encodeURIComponent(code)); const editingId = Number(form.elements.id.value || 0); const duplicate = (data.items || []).some(item => Number(item.citizen_id) === citizenId && Number(item.id) !== editingId); if (sequence !== duplicateCheckSequence || Number(form.elements.citizen_id.value) !== citizenId || Number(form.elements.organization_id.value) !== organizationId) return; form.dataset.duplicate = duplicate ? '1' : ''; $('#associationCitizenSelected').textContent = duplicate ? 'Da la thanh vien doan the nay' : (selected?.full_name || $('#associationCitizenSelected').textContent); setSaveState(); } catch (_) { if (sequence === duplicateCheckSequence) setSaveState(); } }
function setSaveState() { const form = $('#associationForm'); const button = form?.querySelector('button[type="submit"]'); if (!form || !button) return; button.disabled = !form.elements.citizen_id.value || !form.elements.organization_id.value || form.dataset.duplicate === '1'; }
async function save(event) { event.preventDefault(); const form = event.currentTarget; if (!form.elements.citizen_id.value) return toast('Vui long chon nhan khau hien co', 'warning'); if (!form.elements.organization_id.value) return toast('Vui long chon doan the', 'warning'); if (form.dataset.duplicate === '1') return toast('Nhan khau da la thanh vien doan the nay', 'warning'); const payload = Object.fromEntries(new FormData(form).entries()); const id = payload.id; delete payload.id; try { await request(id ? API + '/' + id : API, { method: id ? 'PUT' : 'POST', body: payload }); closeModal('associationModal'); state.catalogs = null; toast('Da luu thanh vien doan the'); load(); } catch (error) { toast(error.message, 'danger'); } }
async function leave(id) { if (!confirm('Chuyen thanh vien sang trang thai da roi doan the?')) return; try { await request(API + '/' + id, { method: 'DELETE' }); toast('Da cap nhat trang thai'); load(); } catch (error) { toast(error.message, 'danger'); } }
async function exportCsv() { const data = await request(API + '/report?' + params()); const lines = [data.headers, ...(data.rows || [])].map(row => row.map(value => '"' + String(value ?? '').replace(/"/g, '""') + '"').join(',')); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' })); link.download = 'danh_sach_doan_the.csv'; link.click(); URL.revokeObjectURL(link.href); }
async function printReport() { const data = await request(API + '/report?' + params()); const win = window.open('', '_blank'); if (!win) return; win.document.write('<title>' + esc(data.title) + '</title><table border="1"><thead><tr>' + data.headers.map(header => '<th>' + esc(header) + '</th>').join('') + '</tr></thead><tbody>' + data.rows.map(row => '<tr>' + row.map(value => '<td>' + esc(value) + '</td>').join('') + '</tr>').join('') + '</tbody></table>'); win.document.close(); win.print(); }
function reset() { state.page = 1; state.search = state.organization_id = state.status = state.area_code = state.from_age = state.to_age = ''; ['associationSearch', 'associationOrganizationFilter', 'associationStatusFilter', 'associationAreaFilter', 'associationAgeFrom', 'associationAgeTo'].forEach(id => { if ($('#' + id)) $('#' + id).value = ''; }); load(); }
function fill(selector, items, first) { const element = $(selector); if (!element) return; element.innerHTML = '<option value="">' + esc(first) + '</option>' + (items || []).map(item => '<option value="' + esc(item.value) + '">' + esc(item.label) + '</option>').join(''); }
function can(action) { return typeof window.TenantAppCanAccess === 'function' ? window.TenantAppCanAccess('associations', action) : true; }
function openModal(id) { window.TenantAppPlatform?.modals?.open?.(id) || window.bootstrap?.Modal?.getOrCreateInstance($('#' + id))?.show(); }
function closeModal(id) { window.TenantAppPlatform?.modals?.close?.(id) || window.bootstrap?.Modal?.getOrCreateInstance($('#' + id))?.hide(); }
function toast(message, type) { window.showToast?.(message, type) || console[type === 'danger' ? 'error' : 'log'](message); }
function debounce(fn, ms) { let timer; return (...args) => { clearTimeout(timer); timer = setTimeout(() => fn(...args), ms); }; }
window.loadAssociations = load;
})();
